    out = [row[:] for row in grid]
    regions = []
    # Find maximal monochrome rectangles that form dense blocks amid noisy surroundings.
    for top in range(h):
        for bottom in range(top + 4, h):
            for left in range(w):
                color = grid[top][left]
                if any(grid[r][left] != color for r in range(top, bottom + 1)):
                    continue
                if left and all(grid[r][left - 1] == color for r in range(top, bottom + 1)):
                    continue
