    """Recolor dense rectangular regions whose large solid core sits in noisy same-color surroundings."""
    h, w = len(grid), len(grid[0])
    candidates = []
    # Enumerate maximal solid rectangles of dimensions evidenced by demonstrations.
    for top in range(h):
